const tabs=(arr,def)=>{const cur=TAB[VIEW]||def;return {cur,html:`<div class="tabs">${arr.map(([v,t,d])=>`<button class="tab ${cur===v?'on':''}" data-a="tab" data-v="${v}"${d?tip(d):''}>${t}</button>`).join('')}</div>`}};
