function courierView(){const my=S.myCourier;const os=S.orders.filter(o=>o.courier===my.id&&!['cancelled'].includes(o.status)).reverse();const bal=custodyBal(my.id);
 return head('أوردراتي','الأوردرات اللي معاك، وتسجيل التسليم والتحصيل')+`<div class="grid2">${kpi('معاك فلوس (عهدة)',mv(bal),'سلّمها لمختار أو حمزة',{hl:1})}${kpi('أوردرات معاك دلوقتي',`${os.filter(o=>o.status==='out').length}`)}</div>
 <div class="card" style="margin-top:14px"><div class="list">${os.slice(0,60).map(o=>{const c=cust(o.cu);const t=oTotals(o);return `<div class="li click" data-a="openOrder" data-v="${o.id}"><div class="main"><div class="t">${esc(o.inv)} · ${esc(c?.name||'')}</div><div class="s">${esc(c?.info?.address||'')} · ${esc(c?.phone||'')}</div></div><div class="e"><div class="b">${t.rem>0.5?'حصّل '+fmt(t.rem):'مدفوع'}</div><span class="pill ${ST[o.status][1]}">${ST[o.status][0]}</span></div></div>`}).join('')||'<div class="empty">مفيش أوردرات معاك</div>'}</div></div>`}

// ---------- PRODUCTION NEEDED ----------
function fmtQ(q,base){if(base==='g')return q>=1000?fmt(q/1000,2)+' كجم':fmt(q,0)+' جم';return fmt(q,q%1?1:0)+' '+unitLbl(base)}
function prodNeeds(range){const t0=today(),lim=range==='today'?t0:range==='tomorrow'?daysAddISO(t0,1):range==='week'?daysAddISO(t0,7):'9999';
 const os=S.orders.filter(o=>['approval','new','prep','ready'].includes(o.status)&&(o.due||o.date).slice(0,10)<=lim);const req={};os.forEach(o=>o.lines.forEach(l=>req[l.pid]=(req[l.pid]||0)+l.q));
 const prods=Object.entries(req).map(([pid,q])=>{const p=prod(pid);return {p,req:q,stock:p.stock,make:Math.max(0,q-p.stock),orders:os.filter(o=>o.lines.some(l=>l.pid===pid)).map(o=>o.inv)}}).sort((a,b)=>b.make-a.make);
 const rNeed={},mNeed={};const addM=(id,q)=>mNeed[id]=(mNeed[id]||0)+q,addR=(id,q)=>rNeed[id]=(rNeed[id]||0)+q;
 prods.forEach(r=>{if(!r.make)return;r.p.comps.forEach(c=>c.k==='r'?addR(c.id,c.q*r.make):addM(c.id,c.q*r.make));r.p.pack.forEach(c=>addM(c.id,(c.perCarton?c.q/(r.p.ppc||1):c.q)*r.make))});
 const level={};const lv=(id,d,seen)=>{if(seen.has(id)||!rec(id))return;seen.add(id);level[id]=Math.max(level[id]||0,d);rec(id).inputs.filter(x=>x.k==='r').forEach(x=>lv(x.id,d+1,new Set(seen)))};
 S.products.forEach(p=>p.comps.filter(c=>c.k==='r').forEach(c=>lv(c.id,1,new Set())));const semis=[],batches={};
 Object.keys(level).sort((a,b)=>level[a]-level[b]).forEach(id=>{const need=rNeed[id]||0;if(!need)return;const r=rec(id);
  if(r.byproduct){const src=rec(r.src);const extra=(batches[r.src]||0)*(src&&src.by?src.by.q:0);semis.push({r,need,stock:r.stock,extra,make:Math.max(0,need-r.stock-extra),batches:0,by:true});return}
  const make=Math.max(0,need-r.stock);const b=make>0&&r.yield>0?Math.ceil(make/r.yield):0;batches[id]=b;semis.push({r,need,stock:r.stock,make,batches:b,out:b*r.yield});r.inputs.forEach(x=>x.k==='r'?addR(x.id,x.q*b):addM(x.id,x.q*b))});
 const mats=Object.entries(mNeed).filter(([id,q])=>q>0.0001&&mat(id)).map(([id,need])=>{const m=mat(id);const short=Math.max(0,need-m.stock);const cheap=m.prices.slice().sort((a,b)=>a.p-b.p)[0];return {m,need,stock:m.stock,short,shortPU:Math.ceil(short/m.size*10)/10,cheap}}).sort((a,b)=>(b.short>0)-(a.short>0));
 return {orders:os,prods,semis,mats}}
function makeTab(){const range=TAB.makeRange||'all';const N=prodNeeds(range);const short=N.mats.filter(x=>x.short>0);
 return `<div class="seg" style="margin-bottom:12px">${[['today','النهارده'],['tomorrow','لحد بكرة'],['week','الأسبوع ده'],['all','كل المفتوح']].map(([v,t])=>`<button class="${range===v?'on':''}" data-a="makeRange" data-v="${v}">${t}</button>`).join('')}</div>
 <div class="grid3">${kpi('أوردرات داخلة',`${N.orders.length}`,'لسه ما خرجتش مع المندوب')}${kpi('قطع لازم تتصنع',`${fmt(N.prods.reduce((s,r)=>s+r.make,0))}`,'من '+fmt(N.prods.reduce((s,r)=>s+r.req,0))+' مطلوبة (محجوزة)')}${kpi('خامات ناقصة',`${short.length}`,short.length?'لازم تتشترى':'الخامات مكفية',{cls:short.length?'down':'up'})}</div>
 <div class="card" style="margin-top:14px"><h2>1) المنتجات</h2><div class="tbl-wrap" style="margin-top:8px"><table><tr><th>المنتج</th><th class="n">مطلوب (محجوز)</th><th class="n">في المخزن</th><th class="n">صنّع</th><th>الأوردرات</th><th></th></tr>
 ${N.prods.map(r=>`<tr><td>${esc(r.p.name)}</td><td class="n">${fmt(r.req)}</td><td class="n">${fmt(r.stock)}</td><td class="n need-cell ${r.make?'down':'up'}">${r.make?fmt(r.make):'✓'}</td><td class="small muted">${r.orders.join(' ')}</td><td>${r.make&&canSee('production')?`<button class="btn sec sm" data-a="quickProd" data-k="p" data-v="${r.p.id}" data-q="${r.make}">سجّل</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">مفيش أوردرات في الفترة دي</td></tr>'}</table></div></div>
 <div class="card" style="margin-top:14px"><h2>2) المكونات النص مصنعة</h2><div class="tbl-wrap" style="margin-top:8px"><table><tr><th>المكون</th><th class="n">محتاج</th><th class="n">موجود</th><th class="n">اعمل</th><th></th></tr>
 ${N.semis.map(s=>`<tr><td>${esc(s.r.name)}</td><td class="n">${fmtQ(s.need,s.r.out)}</td><td class="n">${fmtQ(s.stock,s.r.out)}</td><td class="n need-cell">${s.by?(s.make?'ناقص '+fmtQ(s.make,'g'):'✓'):s.batches?s.batches+' وجبة = '+fmtQ(s.out,s.r.out):'✓'}</td><td>${s.batches&&canSee('production')?`<button class="btn sec sm" data-a="quickProd" data-k="r" data-v="${s.r.id}" data-q="${s.batches}">سجّل</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">مش محتاج</td></tr>'}</table></div></div>
 <div class="card" style="margin-top:14px"><div class="between"><h2>3) الخامات والتغليف</h2>${short.length&&canSee('suppliers')?'<button class="btn sm" data-a="buyShort">فاتورة شراء بالناقص</button>':''}</div><div class="tbl-wrap" style="margin-top:8px"><table><tr><th>الخامة</th><th class="n">محتاج</th><th class="n">في المخزن</th><th class="n">ناقص</th><th class="n">اشتري</th></tr>
 ${N.mats.map(x=>`<tr${x.short?' style="background:var(--bad-soft)"':''}><td>${esc(x.m.name)}</td><td class="n">${fmtQ(x.need,x.m.base)}</td><td class="n">${fmtQ(x.stock,x.m.base)}</td><td class="n ${x.short?'down b':'up'}">${x.short?fmtQ(x.short,x.m.base):'✓'}</td><td class="n">${x.short?fmt(x.shortPU,1)+' '+esc(x.m.pu):''}</td></tr>`).join('')}</table></div></div>`}
A.makeRange=el=>{TAB.makeRange=el.dataset.v;render()};
A.quickProd=el=>{const k=el.dataset.k,o=k==='r'?rec(el.dataset.v):prod(el.dataset.v);const q=+el.dataset.q;sheet(`<h2>تسجيل إنتاج ${esc(o.name)}</h2><p class="sub">${k==='r'?'بالوجبة: الوجبة بتطلع '+fmtQ(o.yield,o.out):'بالقطعة'}. المكونات هتتخصم من المخزن.</p><div class="field"><label for="qp-q">${k==='r'?'عدد الوجبات':'عدد القطع'}</label><input id="qp-q" type="number" value="${q}"></div><button class="btn block" style="margin-top:12px" data-a="prodSave2" data-k="${k}" data-v="${o.id}">تسجيل</button>`)};
A.prodSave2=async el=>{if(_busy)return;const q=num('qp-q');if(q<=0)return;_busy=true;try{await rpc('record_production',{p:{kind:el.dataset.k,item_id:el.dataset.v,qty:q}});closeSheet();await refresh();toast('اتسجل الإنتاج واتخصمت المكونات')}finally{_busy=false}};
A.buyShort=()=>{const N=prodNeeds(TAB.makeRange||'all');const sh=N.mats.filter(x=>x.short>0);if(!sh.length||!S.suppliers.length){toast('مفيش ناقص أو مفيش موردين');return}const cnt={};sh.forEach(x=>{if(x.cheap)cnt[x.cheap.s]=(cnt[x.cheap.s]||0)+1});const s=Object.keys(cnt).sort((a,b)=>cnt[b]-cnt[a])[0]||S.suppliers[0].id;
 PU={s,d:today(),notes:'ناقص للأوردرات',lines:sh.map(x=>({mid:x.m.id,q:Math.ceil(x.shortPU),p:x.cheap?x.cheap.p:(x.m.last?.p||0),b:x.cheap?x.cheap.b:''})),paid:0,t:myTre()};puSheet()};

// ---------- CUSTOMERS ----------
V.customers=()=>{const b=TAB.custBrand||'all';const list=S.customers.filter(c=>b==='all'||c.brand===b);const tot=S.customers.reduce((s,c)=>s+custLedger(c.id).bal,0);
 return head('العملاء','قائمة أسعار أساسية + أسعار خاصة أو خصم · مدة آجل وحد مديونية · كشف حساب','<button class="btn" data-a="editCust" data-v="">+ عميل</button><button class="btn sec" data-a="custPay">تحصيل على الحساب</button>')+
 `<div class="kpi" style="margin-bottom:10px"><div class="l">إجمالي لينا عند العملاء</div><div class="v up">${money(tot)}</div></div>
 <div class="tabs">${[['all','الكل']].concat(S.brands.map(x=>[x.id,x.name])).map(([v,t])=>`<button class="tab ${b===v?'on':''}" data-a="custBrand" data-v="${v}">${esc(t)}</button>`).join('')}</div>
 ${list.length?`<div class="card"><div class="list">${list.map(c=>{const L=custLedger(c.id);const used=c.limit?L.bal/c.limit:0;return `<div class="li click" data-a="custDetail" data-v="${c.id}"><div class="main"><div class="t">${esc(c.name)} <span class="tag-mini">${c.kind==='person'?'فرد':esc(c.type)}</span> ${c.active?'':'<span class="pill">موقوف</span>'}</div><div class="s">${esc(brand(c.brand).name)} · ${c.pay==='cash'?'كاش':'آجل '+c.days+' يوم · حد '+money(c.limit)}${c.disc?' · خصم '+c.disc+'%':''}${Object.keys(c.special||{}).length?' · أسعار خاصة':''}</div>${c.limit?`<div class="bar" style="margin-top:5px"><i style="width:${Math.min(100,used*100)}%;background:${used>0.9?'var(--bad)':used>0.7?'var(--warn)':'var(--ok)'}"></i></div>`:''}</div><div class="e"><div class="b">${money(L.bal)}</div>${L.overdue>0.5?`<span class="pill bad">متأخر ${fmt(L.overdue)}</span>`:''}</div></div>`}).join('')}</div></div>`:emptyState('لسه مفيش عملاء. ضيف أول مطعم أو كافيه.','<button class="btn" data-a="editCust" data-v="">+ عميل</button>')}`};
A.custBrand=el=>{TAB.custBrand=el.dataset.v;render()};
A.custDetail=el=>{const c=cust(el.dataset.v);const L=custLedger(c.id);sheet(`<div class="between"><h2>${esc(c.name)}</h2><div class="row"><button class="btn sec sm" data-a="editCust" data-v="${c.id}">تعديل</button><button class="btn sec sm" data-a="ctOpen" data-k="c" data-v="${c.id}">البيانات</button></div></div><p class="sub">${esc(c.phone)} · ${c.pay==='cash'?'كاش':'آجل '+c.days+' يوم، حد '+money(c.limit)}</p>
 <div class="tbl-wrap"><table><tr><th>التاريخ</th><th>البيان</th><th class="n">عليه</th><th class="n">دفع</th><th class="n">الرصيد</th></tr>${L.rows.map(r=>`<tr><td>${dShort(r.d)}</td><td>${esc(r.t)}${r.dr&&r.due<today()?' <span class="pill bad">استحق '+dShort(r.due)+'</span>':''}</td><td class="n">${r.dr?fmt(r.dr):''}</td><td class="n">${r.cr?fmt(r.cr):''}</td><td class="n b">${fmt(r.bal)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">مفيش حركات</td></tr>'}</table></div>
 <div class="grid2" style="margin-top:10px">${kpi('الرصيد',money(L.bal))}${kpi('متأخر',money(L.overdue),'',{cls:L.overdue?'down':''})}</div>`)};
A.editCust=el=>{const c=el.dataset.v?cust(el.dataset.v):{id:'',name:'',brand:TAB.custBrand&&TAB.custBrand!=='all'?TAB.custBrand:'melt',kind:'b2b',type:'كافيه',phone:'',pay:'cash',days:0,limit:0,disc:0,special:{},info:{},active:true};
 sheet(`<h2>${c.id?'تعديل عميل':'عميل جديد'}</h2><div class="fgrid"><div class="field"><label for="ec-n">الاسم</label><input id="ec-n" type="text" value="${esc(c.name)}"></div><div class="field"><label for="ec-b">البراند</label><select id="ec-b" data-chg="ecBrand">${S.brands.map(b=>`<option value="${b.id}" ${c.brand===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div>
 <div class="field"><label for="ec-k">النوع</label><select id="ec-k"><option value="b2b" ${c.kind!=='person'?'selected':''}>مطعم / كافيه / شركة</option><option value="person" ${c.kind==='person'?'selected':''}>فرد (مناسبة / فرح)</option></select></div><div class="field"><label for="ec-t">التصنيف</label><select id="ec-t">${['كافيه','مطعم','فندق','شركة','فرد','أخرى'].map(t=>`<option ${c.type===t?'selected':''}>${t}</option>`).join('')}</select></div>
 <div class="field"><label for="ec-ph">الموبايل</label><input id="ec-ph" type="tel" value="${esc(c.phone)}"></div><div class="field"><label for="ec-pay">طريقة التعامل</label><select id="ec-pay"><option value="cash" ${c.pay==='cash'?'selected':''}>كاش</option><option value="credit" ${c.pay==='credit'?'selected':''}>آجل</option></select></div>
 <div class="field"><label for="ec-d">مدة الآجل (يوم)</label><input id="ec-d" type="number" value="${c.days}"></div><div class="field"><label for="ec-l">أقصى مديونية</label><input id="ec-l" type="number" value="${c.limit}"></div>
 <div class="field"><label for="ec-disc">خصم ثابت على الفاتورة %</label><input id="ec-disc" type="number" value="${c.disc}"></div><div class="field"><label for="ec-ev">تاريخ المناسبة (للأفراد)</label><input id="ec-ev" type="date" value="${esc(c.info.eventDate||'')}"></div>
 <div class="field full"><label for="ec-ad">العنوان</label><input id="ec-ad" type="text" value="${esc(c.info.address||'')}"></div>${c.id?`<div class="field full"><label class="small"><input type="checkbox" id="ec-act" ${c.active?'checked':''}> العميل شغال</label></div>`:''}</div>
 <h3 style="margin-top:12px">أسعار خاصة (فاضي = سعر القائمة)</h3><div class="tbl-wrap" id="ec-sp"><table><tr><th>الصنف</th><th class="n">القائمة</th><th class="n">سعر خاص</th></tr>${S.products.filter(p=>p.brand===c.brand).map(p=>`<tr><td>${esc(p.name)}</td><td class="n">${fmt(p.price)}</td><td class="n"><input id="ec-sp-${p.id}" type="number" value="${c.special&&c.special[p.id]||''}" class="inp-sm"></td></tr>`).join('')}</table></div>
 <p class="small muted" style="margin-top:6px">باقي البيانات (الأشخاص، السجل، التواريخ، المرفقات) من «دليل العملاء والموردين».</p><button class="btn block" style="margin-top:12px" data-a="saveCust" data-v="${c.id}">حفظ</button>`)};
A.ecBrand=()=>{toast('احفظ الأول وبعدين حدد الأسعار الخاصة للبراند الجديد')};
A.saveCust=async el=>{const n=val('ec-n').trim();if(!n){toast('اكتب الاسم');return}const old=el.dataset.v?cust(el.dataset.v):null;const special={};S.products.forEach(p=>{const v=num('ec-sp-'+p.id);if(v)special[p.id]=v});const info=Object.assign({},old?old.info:{},{address:val('ec-ad'),eventDate:val('ec-ev'),mobile:(old&&old.info.mobile)||val('ec-ph')});
 const act=document.getElementById('ec-act');await dbx(sb.from('customers').upsert({id:old?old.id:uuid(),name:n,brand:val('ec-b'),kind:val('ec-k'),type:val('ec-t'),phone:val('ec-ph'),pay:val('ec-pay'),days:num('ec-d'),credit_limit:num('ec-l'),disc:num('ec-disc'),special,info,active:act?act.checked:true}));closeSheet();await refresh();toast('اتحفظ العميل')};
A.custPay=()=>{const list=S.customers.filter(c=>custLedger(c.id).bal>0.5);if(!list.length){toast('مفيش أرصدة على العملاء');return}sheet(`<h2>تحصيل على حساب عميل</h2><p class="sub">بيتوزع على أقدم فواتير الأول</p><div class="fgrid"><div class="field full"><label for="cp-c">العميل</label><select id="cp-c">${list.map(c=>`<option value="${c.id}">${esc(c.name)} — عليه ${money(custLedger(c.id).bal)}</option>`).join('')}</select></div><div class="field"><label for="cp-v">المبلغ</label><input id="cp-v" type="number"></div><div class="field"><label for="cp-t">الفلوس فين</label><select id="cp-t">${S.treasuries.map(x=>`<option value="t:${x.id}" ${x.id===myTre()?'selected':''}>${x.holder} — ${x.method}</option>`).join('')}${S.couriers.filter(x=>x.active).map(x=>`<option value="co:${x.id}">مع المندوب ${esc(x.name)} (عهدة)</option>`).join('')}</select></div>${bdField('cp-d')}</div><button class="btn block" style="margin-top:12px" data-a="custPaySave">تسجيل</button>`)};
A.custPaySave=async()=>{if(_busy)return;const v=num('cp-v');if(v<=0){toast('اكتب المبلغ');return}const [k,id]=val('cp-t').split(':');_busy=true;try{await rpc('record_payment',{p:{cu:val('cp-c'),amount:v,treasury_id:k==='t'?id:'',courier_id:k==='co'?id:'',d:bdVal('cp-d')}});closeSheet();await refresh();toast('اتسجل التحصيل')}finally{_busy=false}};

// ---------- CASH ----------
V.cash=()=>{const holders=[...new Set(S.treasuries.map(t=>t.holder))];const cs=S.couriers.filter(c=>Math.abs(custodyBal(c.id))>0.5||unsettledFees(c.id)>0);
 return head('التحصيل والخزن','كل جنيه معروف هو فين: عند مين، وبأنهي طريقة، أو مع أنهي مندوب','<button class="btn" data-a="transfer">تحويل بين الخزن</button><button class="btn sec" data-a="custPay">تحصيل على حساب عميل</button>')+
 holders.map(h=>{const ts=S.treasuries.filter(t=>t.holder===h);return `<div class="card" style="margin-bottom:12px"><div class="between"><h2>عند ${esc(h)}</h2><b class="num">${money(ts.reduce((s,t)=>s+t.bal,0))}</b></div><div class="grid3" style="margin-top:10px">${ts.map(t=>kpi(t.method,mv(t.bal),'اضغط لحركات الخزنة',{tip:'رصيد خزنة '+t.holder+' — '+t.method}).replace('class="kpi  "',`class="kpi go" data-a="treMoves" data-v="${t.id}" tabindex="0"`)).join('')}</div></div>`}).join('')+
 `<div class="card" style="margin-bottom:12px"><h2 class="sec-title">فلوس مع المناديب (عهدة) ${ti('اللي حصّله المندوب من العملاء ولسه ما سلّمهوش')}</h2><div class="list" style="margin-top:6px">${cs.map(c=>`<div class="li"><div class="main"><div class="t">${esc(c.name)} <span class="tag-mini">${c.kind==='main'?'أساسي':'خارجي'}</span></div><div class="s">معاه ${money(custodyBal(c.id))}${unsettledFees(c.id)?' · أجرة مستحقة '+money(unsettledFees(c.id)):''}</div></div><button class="btn sm" data-a="settle" data-v="${c.id}">تسوية</button></div>`).join('')||'<div class="empty">مفيش فلوس مع المناديب</div>'}</div></div>
 <div class="card"><h2>آخر الحركات</h2><div class="list">${S.cashLog.slice(0,40).map(l=>`<div class="li"><div class="main"><div class="t">${esc(l.note)}</div><div class="s">${dShort(l.d)} · ${tName(l.t)} · ${esc(l.by)}</div></div><div class="e ${l.amt>=0?'up':'down'} b">${l.amt>=0?'+':''}${fmt(l.amt)}</div></div>`).join('')||'<div class="empty">مفيش حركات لسه</div>'}</div></div>`};
A.treMoves=el=>{const t=tre(el.dataset.v);const L=S.cashLog.filter(l=>l.t===t.id);sheet(`<h2>خزنة ${t.holder} — ${t.method}</h2><p class="sub">الرصيد ${money(t.bal)} · الافتتاحي ${money(t.opening)}</p><div class="list">${L.map(l=>`<div class="li"><div class="main"><div class="t">${esc(l.note)}</div><div class="s">${dShort(l.d)} · ${esc(l.by)}</div></div><div class="e b ${l.amt>=0?'up':'down'}">${l.amt>=0?'+':''}${fmt(l.amt)}</div></div>`).join('')||'<div class="empty">مفيش حركات</div>'}</div>`)};
A.transfer=()=>sheet(`<h2>تحويل بين الخزن</h2><div class="fgrid"><div class="field"><label for="tf-a">من</label><select id="tf-a">${trOpts(myTre())}</select></div><div class="field"><label for="tf-b">إلى</label><select id="tf-b">${trOpts('')}</select></div><div class="field"><label for="tf-v">المبلغ</label><input id="tf-v" type="number"></div><div class="field"><label for="tf-n">ملاحظة</label><input id="tf-n" type="text"></div></div><button class="btn block" style="margin-top:12px" data-a="transferSave">تحويل</button>`);
A.transferSave=async()=>{const a=val('tf-a'),b=val('tf-b'),v=num('tf-v');if(a===b||v<=0){toast('اختار خزنتين مختلفتين ومبلغ');return}await rpc('transfer_cash',{p_from:a,p_to:b,p_amount:v,p_note:(val('tf-n')||'')+' '+tName(a)+' ← '+tName(b)});closeSheet();await refresh();toast('اتحوّل '+money(v))};
A.settle=el=>{const c=cour(el.dataset.v);const bal=custodyBal(c.id),fee=unsettledFees(c.id);sheet(`<h2>تسوية ${esc(c.name)}</h2><p class="sub">معاه ${money(bal)}${fee?' · أجرته المستحقة '+money(fee):''}</p><div class="fgrid"><div class="field"><label for="st-a">المبلغ اللي سلّمه</label><input id="st-a" type="number" value="${Math.max(0,bal)}"></div><div class="field"><label for="st-f">أجرة تتخصم (للخارجي)</label><input id="st-f" type="number" value="${c.kind==='external'?fee:0}"></div><div class="field full"><label for="st-t">الصافي اتسلّم في</label><select id="st-t">${trOpts(myTre())}</select></div></div><button class="btn block" style="margin-top:12px" data-a="settleSave" data-v="${c.id}">تسوية</button>`)};
A.settleSave=async el=>{if(_busy)return;_busy=true;try{await rpc('settle_courier',{p:{courier_id:el.dataset.v,amount:num('st-a'),fee:num('st-f'),treasury_id:val('st-t')}});closeSheet();await refresh();toast('اتسوّى حساب المندوب')}finally{_busy=false}};

// ---------- COURIERS ----------
V.couriers=()=>{const m=today().slice(0,7);return head('المناديب والتوصيل','أساسي بمرتب وعمولة اختيارية · خارجي بأجرة على الأوردر','<button class="btn" data-a="editCourier" data-v="">+ مندوب</button>')+
 (S.couriers.length?S.couriers.map(d=>{const os=S.orders.filter(o=>o.courier===d.id&&billable(o)&&o.date.slice(0,7)===m);const u=S.users.find(x=>x.id===d.userId);
  return `<div class="card" style="margin-bottom:10px"><div class="between"><div><h2>${esc(d.name)} ${d.active?'':'<span class="pill">موقوف</span>'}</h2><div class="small muted">${d.kind==='main'?'أساسي':'خارجي'} · ${esc(d.phone)}${u?' · بيدخل باسم '+esc(u.name):''}</div></div><button class="btn sec sm" data-a="editCourier" data-v="${d.id}">تعديل</button></div>
  <div class="grid3" style="margin-top:10px">${kpi('أوردرات الشهر',`${os.length}`)}${d.kind==='main'?kpi('العمولة '+(d.commOn?'('+fmt(d.comm)+' ج/أوردر)':'(مقفولة)'),mv(d.commOn?os.length*d.comm:0)):kpi('أجرة الأوردر',mv(d.perOrder))}${kpi('معاه عهدة',mv(custodyBal(d.id)))}</div></div>`}).join(''):emptyState('ضيف المناديب: الأساسي بمرتبه، والخارجي بأجرة الأوردر.','<button class="btn" data-a="editCourier" data-v="">+ مندوب</button>'))};
A.editCourier=el=>{const d=el.dataset.v?cour(el.dataset.v):{id:'',name:'',kind:'main',phone:'',salary:0,comm:0,commOn:false,perOrder:0,userId:null,active:true};
 sheet(`<h2>${d.id?'تعديل مندوب':'مندوب جديد'}</h2><div class="fgrid"><div class="field"><label for="cr-n">الاسم</label><input id="cr-n" type="text" value="${esc(d.name)}"></div><div class="field"><label for="cr-k">النوع</label><select id="cr-k"><option value="main" ${d.kind==='main'?'selected':''}>أساسي</option><option value="external" ${d.kind==='external'?'selected':''}>خارجي</option></select></div>
 <div class="field"><label for="cr-p">الموبايل</label><input id="cr-p" type="tel" value="${esc(d.phone)}"></div><div class="field"><label for="cr-s">المرتب (للأساسي)</label><input id="cr-s" type="number" value="${d.salary}"></div>
 <div class="field"><label for="cr-c">العمولة على الأوردر</label><input id="cr-c" type="number" value="${d.comm}"></div><div class="field" style="justify-content:flex-end"><label class="small"><input type="checkbox" id="cr-co" ${d.commOn?'checked':''}> العمولة مفعّلة</label></div>
 <div class="field"><label for="cr-o">أجرة الأوردر (للخارجي)</label><input id="cr-o" type="number" value="${d.perOrder}"></div><div class="field"><label for="cr-u">بيدخل السيستم بحساب ${ti('للمندوب الأساسي: اربطه بحسابه علشان يشوف أوردراته ويسجل التسليم والتحصيل من موبايله')}</label><select id="cr-u"><option value="">— مش بيدخل —</option>${S.users.filter(u=>!u.owner).map(u=>`<option value="${u.id}" ${d.userId===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div>
 ${d.id?`<div class="field full"><label class="small"><input type="checkbox" id="cr-a" ${d.active?'checked':''}> شغال</label></div>`:''}</div><button class="btn block" style="margin-top:12px" data-a="saveCourier" data-v="${d.id}">حفظ</button>`)};
A.saveCourier=async el=>{const n=val('cr-n').trim();if(!n){toast('اكتب الاسم');return}const a=document.getElementById('cr-a');const k=val('cr-k');
 await dbx(sb.from('couriers').upsert({id:el.dataset.v||uuid(),name:n,kind:k,phone:val('cr-p'),salary:num('cr-s'),comm:num('cr-c'),comm_on:document.getElementById('cr-co').checked,per_order:num('cr-o'),user_id:k==='main'?(val('cr-u')||null):null,active:a?a.checked:true}));closeSheet();await refresh();toast('اتحفظ المندوب')};

