V.returns=()=>{const m=today().slice(0,7);const rs=S.returns.slice().reverse();const cost=rs.filter(r=>r.d.slice(0,7)===m).reduce((s,r)=>s+r.cost,0);const sales=S.orders.filter(o=>billable(o)&&o.date.slice(0,7)===m).reduce((s,o)=>s+o.total,0);
 return head('المرتجعات والهالك','مرتجع بخصم من حساب العميل، أو استبدال والتكلفة علينا · السبب إجباري','<button class="btn" data-a="newReturn">+ مرتجع</button>')+
 `<div class="grid2">${kpi('تكلفة الهالك الشهر ده',can('cost')?mv(cost):hidden())}${kpi('نسبته من المبيعات',can('cost')?pct(cost/(sales||1)):hidden())}</div>
 <div class="card" style="margin-top:12px"><div class="list">${rs.map(r=>`<div class="li"><div class="main"><div class="t">${esc(prod(r.pid)?.name||'')} × ${fmt(r.q)} · ${esc(cust(r.cu)?.name||'')}</div><div class="s">${dShort(r.d)} · ${esc(r.reason)}${r.order?' · '+esc(ordr(r.order)?.inv||''):''}</div></div><div class="e"><span class="pill ${r.kind==='deduct'?'warn':'acc'}">${r.kind==='deduct'?'خصم '+fmt(r.value):'استبدال'}</span></div></div>`).join('')||'<div class="empty">مفيش مرتجعات</div>'}</div></div>`};
A.newReturn=()=>{if(!S.customers.length)return;sheet(`<h2>تسجيل مرتجع</h2><div class="fgrid"><div class="field"><label for="r-c">العميل</label><select id="r-c" data-chg="retCu">${S.customers.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="r-o">الفاتورة</label><select id="r-o"><option value="">— من غير فاتورة —</option>${S.orders.filter(o=>o.cu===S.customers[0].id&&billable(o)).reverse().map(o=>`<option value="${o.id}">${esc(o.inv)} ${dShort(o.date)}</option>`).join('')}</select></div>
 <div class="field"><label for="r-p">الصنف</label><select id="r-p">${S.products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label for="r-q">الكمية</label><input id="r-q" type="number" value="1"></div>
 <div class="field full"><label for="r-k">النوع</label><select id="r-k"><option value="deduct">مرتجع بخصم قيمته من حساب العميل</option><option value="replace">استبدال بقطعة جديدة (الحساب ما يتأثرش)</option></select></div><div class="field full"><label for="r-r">السبب (إجباري)</label><input id="r-r" type="text" placeholder="تلف في النقل، جودة، انتهاء صلاحية..."></div>${bdField('r-d')}</div><button class="btn block" style="margin-top:12px" data-a="returnSave">تسجيل</button>`)};
A.retCu=el=>{const s=document.getElementById('r-o');s.innerHTML='<option value="">— من غير فاتورة —</option>'+S.orders.filter(o=>o.cu===el.value&&billable(o)).reverse().map(o=>`<option value="${o.id}">${esc(o.inv)} ${dShort(o.date)}</option>`).join('')};
A.returnSave=async()=>{if(!val('r-r').trim()){toast('اكتب السبب');return}const pid=val('r-p'),q=Math.max(1,num('r-q'));await rpc('record_return',{p:{cu:val('r-c'),order_id:val('r-o'),product_id:pid,qty:q,kind:val('r-k'),reason:val('r-r'),cost:+(pcost(prod(pid)).mat*q).toFixed(2),d:bdVal('r-d')}});closeSheet();await refresh();toast('اتسجل المرتجع')};

