V.stock=()=>{const tb=tabs([['m','خامات وتغليف'],['r','نص مصنع'],['p','منتج تام'],['count','جرد آخر الشهر'],['open','رصيد أول المدة','الموجود يوم بداية السيستم بتكلفته. بيظبط الأرصدة وبيبقى مخزون أول المدة لأول إقفال']],'m');const sv=stockValue();const k=today().slice(0,7);const cnt=S.counts[k]||{status:'draft',items:{}};const sc=can('cost');
 const rowsOf=kind=>kind==='m'?S.materials.map(m=>({id:m.id,n:m.name,q:m.stock,u:unitLbl(m.base),pu:m.size,pul:m.pu,v:m.stock*m.avg,uc:m.avg})):kind==='r'?S.recipes.map(r=>({id:r.id,n:r.name,q:r.stock,u:unitLbl(r.out),v:r.stock*recInfo(r.id).unit,uc:recInfo(r.id).unit})):S.products.map(p=>({id:p.id,n:p.name,q:p.stock,u:'قطعة',v:p.stock*pcost(p).mat,uc:pcost(p).mat}));
 const reserved={};S.orders.filter(o=>['approval','new','prep','ready'].includes(o.status)).forEach(o=>o.lines.forEach(l=>reserved[l.pid]=(reserved[l.pid]||0)+l.q));
 let body='';
 if(tb.cur==='open')body=openingTab();else if(tb.cur!=='count')body=`<div class="card"><div class="tbl-wrap"><table><tr><th>الصنف</th><th class="n">الرصيد</th>${tb.cur==='p'?'<th class="n">محجوز للأوردرات</th><th class="n">متاح</th>':''}${tb.cur==='m'?'<th class="n">بوحدة الشراء</th>':''}${sc?'<th class="n">القيمة</th>':''}</tr>${rowsOf(tb.cur).map(r=>`<tr><td>${esc(r.n)}</td><td class="n">${fmt(r.q)} ${r.u}</td>${tb.cur==='p'?`<td class="n">${fmt(reserved[r.id]||0)}</td><td class="n ${r.q-(reserved[r.id]||0)<0?'down':''}">${fmt(r.q-(reserved[r.id]||0))}</td>`:''}${tb.cur==='m'?`<td class="n">${esc(pkgFmt(mat(r.id),r.q))}</td>`:''}${sc?`<td class="n">${fmt(r.v)}</td>`:''}</tr>`).join('')||'<tr><td colspan="5" class="empty">مفيش أصناف</td></tr>'}</table></div>${tb.cur!=='m'?'<p class="small muted" style="margin-top:8px">لتسجيل رصيد أول مدة للنص مصنع أو المنتج التام، استخدم «جرد آخر الشهر» واكتب الكمية الفعلية واعتمده.</p>':''}</div>`;
 else{const ap=cnt.status==='approved';body=`<div class="card"><div class="between"><h2>جرد ${MONTHS[+k.slice(5)-1]} ${k.slice(0,4)}</h2>${ap?`<span class="pill ok">اتعتمد · ${esc(cnt.by||'')}</span>`:'<span class="pill warn">مسودة</span>'}</div><p class="sub">اكتب الكمية الفعلية (بتتحفظ مسودة أول بأول). الفرق بيتحسب بالتكلفة، والعجز بيتسجل هالك.${ap?' عجز '+money(cnt.loss)+' · زيادة '+money(cnt.gain):''}</p>
  ${['m','r','p'].map(kind=>`<h3 style="margin-top:10px">${{m:'خامات وتغليف',r:'نص مصنع',p:'منتج تام'}[kind]}</h3><div class="tbl-wrap"><table><tr><th>الصنف</th><th class="n">الفعلي</th>${kind==='m'?'':'<th class="n">الفرق</th>'}</tr>${rowsOf(kind).map(r=>{const a=cnt.items[kind+':'+r.id];const diff=a!=null&&a!==''?(a-r.q)*r.uc:null;return `<tr><td>${esc(r.n)}<div class="small muted">السيستم: ${kind==='m'?esc(pkgFmt(mat(r.id),r.q)):fmt(r.q)+' '+r.u}</div></td><td class="n">${kind==='m'?pkgInputs('cp',mat(r.id),cnt.items['mb:'+r.id],'cntPk',cnt.items['m:'+r.id])+`<div id="cd-m-${r.id}" style="margin-top:4px">${cntDiffHTML('m',r.id,a)}</div>`:`<input type="number" class="inp-sm" id="cnt-${kind}-${r.id}" value="${a??''}" placeholder="${fmt(r.q)}" data-chg="cntIn" data-live="cntIn" data-k="${kind}:${r.id}">`}</td>${kind==='m'?'':`<td class="n" id="cd-${kind}-${r.id}">${cntDiffHTML(kind,r.id,a)}</td>`}</tr>`}).join('')}</table></div>`).join('')}
  <div id="cnt-tot" style="margin-top:12px">${cntTotalsHTML()}</div>${can('approve')?`<button class="btn block" style="margin-top:12px" data-a="approveCount">اعتماد الجرد وتعديل الأرصدة</button>`:'<p class="small muted">اعتماد الجرد للمالك</p>'}</div>`}
 return head('المخزن والجرد','مكان تخزين واحد · 3 أقسام · المنتج بيتخصم لما الأوردر يخرج مع المندوب')+(sc?`<div class="grid3">${kpi('خامات وتغليف',mv(sv.m))}${kpi('نص مصنع',mv(sv.r))}${kpi('منتج تام',mv(sv.p))}</div>`:'')+`<div style="margin-top:12px">${tb.html}</div>`+body};
let _cntT=null;
A.cntIn=el=>{const k=today().slice(0,7);const c=S.counts[k]=S.counts[k]||{status:'draft',items:{}};if(el.value==='')delete c.items[el.dataset.k];else c.items[el.dataset.k]=+el.value;cntRefreshCell(el.dataset.k);clearTimeout(_cntT);_cntT=setTimeout(async()=>{await dbx(sb.from('stock_counts').upsert({month:k,status:c.status==='approved'?'approved':'draft',items:c.items,updated_at:new Date().toISOString()},{onConflict:'month'}))},800)};
A.approveCount=async()=>{const k=today().slice(0,7);const c=S.counts[k]||{items:{}};const items=Object.entries(c.items).filter(([key,v])=>/^[mrp]:/.test(key)&&v!==''&&v!=null).map(([key,actual])=>{const [kind,id]=key.split(':');const uc=kind==='m'?(mat(id)?.avg||0):kind==='r'?recInfo(id).unit:pcost(prod(id)).mat;return {kind,id,actual:+actual,unit_cost:uc}});
 if(!items.length){toast('اكتب الكميات الفعلية الأول');return}let after=stockValue().all;items.forEach(it=>{const o=it.kind==='m'?mat(it.id):it.kind==='r'?rec(it.id):prod(it.id);after+=(it.actual-o.stock)*it.unit_cost});
 await rpc('approve_count',{p:{month:k,items,value:+after.toFixed(2)}});await refresh();toast('اتعتمد الجرد واتعدّلت الأرصدة')};

