function ctSheet(){const i=CT.info;const e=entity(CT.k,CT.id);sheet(`<h2>بيانات ${esc(e.name)}</h2>
 <h3 style="margin-top:12px;color:var(--accent)">الأشخاص اللي بنتعامل معاهم ${ti('المالك، المدير، مسؤول المشتريات... كل واحد بصفته. التهنئة هتروح لكل واحد باسمه')}</h3>
 ${i.people.map((p,ix)=>`<div class="card flat" style="padding:10px;margin-bottom:8px"><div class="fgrid"><div class="field"><label for="pp-n-${ix}">الاسم</label><input id="pp-n-${ix}" type="text" value="${esc(p.name)}"></div><div class="field"><label for="pp-r-${ix}">الصفة</label><select id="pp-r-${ix}">${ROLES.map(r=>`<option ${p.role===r?'selected':''}>${r}</option>`).join('')}</select></div>
 <div class="field"><label for="pp-m-${ix}">الموبايل</label><input id="pp-m-${ix}" type="tel" value="${esc(p.mobile)}"></div><div class="field"><label for="pp-w-${ix}">واتساب</label><input id="pp-w-${ix}" type="tel" value="${esc(p.whatsapp)}"></div>
 <div class="field"><label for="pp-b-${ix}">عيد الميلاد</label><input id="pp-b-${ix}" type="date" value="${esc(p.bday)}"></div><div class="field" style="justify-content:flex-end"><label class="small"><input type="checkbox" id="pp-c-${ix}" ${p.current!==false?'checked':''}> لسه شغال هناك</label></div></div><button class="btn ghost sm" data-a="ppDel" data-i="${ix}">حذف الشخص</button></div>`).join('')}<button class="btn sec sm" data-a="ppAdd">+ شخص</button>
 ${CG.map(g=>`<h3 style="margin-top:14px;color:var(--accent)">${g}</h3><div class="fgrid">${CF.filter(f=>f[2]===g).map(f=>`<div class="field ${f[0]==='notes'||f[0]==='address'?'full':''}"><label for="ce-${f[0]}">${f[1]}</label><input id="ce-${f[0]}" type="${f[3]==='date'?'date':f[3]==='tel'?'tel':'text'}" value="${esc(i[f[0]]||'')}"></div>`).join('')}</div>`).join('')}
 <h3 style="margin-top:14px;color:var(--accent)">تفاصيل إضافية</h3>${i.custom.map((c,ix)=>`<div class="row" style="flex-wrap:nowrap;margin-bottom:6px"><input type="text" id="cc-k-${ix}" value="${esc(c.k)}" placeholder="اسم الحقل" style="flex:1"><input type="text" id="cc-v-${ix}" value="${esc(c.v)}" placeholder="القيمة" style="flex:1.4"><button class="icon-btn" data-a="ccDel" data-i="${ix}" aria-label="حذف">×</button></div>`).join('')}<button class="btn sec sm" data-a="ccAdd">+ حقل</button>
 <h3 style="margin-top:14px;color:var(--accent)">مرفقات (العقد أو الكارت) ${ti('محفوظة بشكل خاص، ومحدش يشوفها غير اللي معاه صلاحية الدليل')}</h3><div class="small muted">${i.files.map((f,ix)=>`<span class="pill">${esc(f.name)} <button class="btn ghost sm" data-a="cfDel" data-i="${ix}">×</button></span>`).join(' ')}</div><input type="file" accept="image/*" id="ce-file" data-chg="cfAdd" style="margin-top:6px">
 <button class="btn block" style="margin-top:14px" data-a="ctSave">حفظ</button>`)}
A.ppAdd=()=>{ctRead();CT.info.people.push({name:'',role:'المالك',mobile:'',whatsapp:'',bday:'',current:true});ctSheet()};
A.ppDel=el=>{ctRead();CT.info.people.splice(+el.dataset.i,1);ctSheet()};
A.ccAdd=()=>{ctRead();CT.info.custom.push({k:'',v:''});ctSheet()};A.ccDel=el=>{ctRead();CT.info.custom.splice(+el.dataset.i,1);ctSheet()};
A.cfDel=el=>{ctRead();CT.info.files.splice(+el.dataset.i,1);ctSheet()};
A.cfAdd=el=>{const f=el.files&&el.files[0];if(!f)return;ctRead();toast('بيرفع المرفق...');imgToData(f,1400,async d=>{const path=CT.k+'/'+CT.id+'/'+Date.now()+'.jpg';const {error}=await sb.storage.from('docs').upload(path,dataToBlob(d),{contentType:'image/jpeg'});if(error){toast('الرفع فشل: '+error.message);return}CT.info.files.push({name:f.name,path});ctSheet();toast('اترفع المرفق، اضغط حفظ')})};
A.ctSave=async()=>{ctRead();const i=CT.info;i.people=i.people.filter(p=>p.name.trim());i.custom=i.custom.filter(c=>c.k||c.v);const lead=i.people.find(p=>p.current!==false&&/مالك|صاحب/.test(p.role))||i.people[0];if(lead){i.contact=lead.name;i.role=lead.role}
 await dbx(sb.from(CT.k==='c'?'customers':'suppliers').update({info:i}).eq('id',CT.id));closeSheet();await refresh();toast('اتحفظت البيانات')};

