const _menuPagesBase=menuPages;
menuPages=function(b,layout){const cu=TAB.menuGen&&TAB.menuGen.cu;if(!cu)return _menuPagesBase(b,layout);const c=cust(cu);const keep=S.products.map(p=>p.price);S.products.forEach(p=>{if(c.special&&+c.special[p.id])p.price=+c.special[p.id]});
 try{const pages=_menuPagesBase(b,layout);pages[0]=pages[0].replace('قائمة الأسعار</div>',`قائمة الأسعار</div><div style="margin-top:14px;padding:10px 24px;border:1px solid var(--mk-acc);border-radius:40px;font-size:16px;color:#5b3a1e">مقدَّمة خصيصًا لـ <b>${esc(c.name)}</b>${c.disc?' · خصم '+c.disc+'% على الفاتورة':''}</div>`);return pages}finally{S.products.forEach((p,i)=>p.price=keep[i])}};
