V.menu=()=>{const html=_menuView();const b=TAB.menuBrand||'melt';const M=TAB.menuGen=TAB.menuGen||{layout:'catalog'};const c=M.cu?cust(M.cu):null;const other=c?S.menuLog.filter(l=>l.cu===c.id&&l.brand!==b):[];
 const extra=`<div class="field full" style="margin-top:10px"><label for="mn-cu">الأسعار</label><select id="mn-cu" data-chg="menuCu"><option value="">قائمة الأسعار الأساسية</option>${S.customers.map(x=>`<option value="${x.id}" ${M.cu===x.id?'selected':''}>أسعار ${esc(x.name)}${x.brand!==b?' (براند تاني)':''}</option>`).join('')}</select></div>
 ${c&&c.brand!==b?`<div class="alert warn" style="margin-top:10px"><span class="dot"></span><div>${esc(c.name)} عميل ${esc(brand(c.brand).name)}، والمنيو ده لـ ${esc(brand(b).name)}. <label class="small"><input type="checkbox" id="mn-ok" ${M.ok?'checked':''} data-chg="menuOk"> أيوه، عايز أبعتله المنيو ده برضه</label></div></div>`:''}
 ${other.length?`<div class="alert info" style="margin-top:8px"><span class="dot"></span><div>${esc(c.name)} خد قبل كده منيو ${esc(brand(other[other.length-1].brand).name)} يوم ${dShort(other[other.length-1].d)}.</div></div>`:''}`;
 return html.replace('<p class="small muted" style="margin-top:8px">المنيو بأسعار عميل معيّن هيتضاف مع العملاء في الدفعة 2.</p>',extra)};
A.menuCu=el=>{TAB.menuGen.cu=el.value;TAB.menuGen.ok=false;render()};A.menuOk=el=>{TAB.menuGen.ok=el.checked};
const _menuPdf=A.menuPdf,_menuPrev=A.menuPreview;
function menuCheck(){const M=TAB.menuGen;const b=TAB.menuBrand||'melt';const c=M.cu?cust(M.cu):null;if(c&&c.brand!==b&&!M.ok){toast('العميل ده تبع براند تاني. علّم «أيوه، عايز أبعتله» الأول');return false}return true}
