A.yearClose=async el=>{const y=el.dataset.v;if(!confirm('إقفال سنة '+y+'؟'))return;const ks=Array.from({length:12},(_,i)=>y+'-'+String(i+1).padStart(2,'0')).filter(k=>S.closings[k]);const all=ks.map(k=>monthPL(k));const s=f=>+all.reduce((a,m)=>a+(m[f]||0),0).toFixed(2);
 await rpc('close_year',{p:{year:y,pl:{sales:s('sales'),cogs:s('cogs'),exp:s('exp'),net:s('net')}}});await refresh();toast('اتقفلت السنة')};
