// ---------- settings card ----------
const _prefsV=V.prefs;
V.prefs=()=>{const st=S.settings;const g=st.geo;if(!me().owner)return _prefsV();
 const card=`<div class="card" style="margin-top:12px"><h2>الحضور والمرتبات والإقفال</h2><div class="fgrid" style="margin-top:8px">
 <div class="field full"><label>موقع المصنع ${ti('اقف جوه المصنع واضغط الزرار. الموظف مش هيقدر يسجل حضور غير لو جوه المسافة دي')}</label><div class="row"><button class="btn sec sm" data-a="setGeo">📍 حدد موقع المصنع من موبايلي</button><span class="small ${g?'up':'down'}">${g?'متحدد ('+(+g.lat).toFixed(5)+', '+(+g.lng).toFixed(5)+')':'لسه ما اتحددش'}</span>${g?`<a class="small" href="https://maps.google.com/?q=${g.lat},${g.lng}" target="_blank" rel="noopener">شوفه على الخريطة ↗</a>`:''}</div></div>
 <div class="field"><label for="s3-r">المسافة المسموحة (متر)</label><input id="s3-r" type="number" value="${g&&g.radius||st.radius||100}"></div><div class="field"><label for="s3-g">سماح التأخير (دقايق) ${ti('عدد الدقايق اللي ما بتتحسبش تأخير. 0 = أي تأخير بيتخصم')}</label><input id="s3-g" type="number" value="${st.graceMin||0}"></div>
 <div class="field"><label for="s3-oi">قيمة المخزون يوم بداية السيستم ${ti('بتستخدم كمخزون أول المدة لأول شهر يتقفل')}</label><input id="s3-oi" type="number" value="${st.openingInv||0}"></div><div class="field"><label for="s3-vm">مضاعفات التقييم (شهور)</label><input id="s3-vm" type="text" value="${(st.valMult||[24,36]).join('، ')}"></div>
 <div class="field full"><label for="s3-ec">بنود المصروفات</label><input id="s3-ec" type="text" value="${esc((st.expCats||[]).join('، '))}"></div><div class="field full"><label for="s3-fc">المصروفات الثابتة (بتتسأل عنها وقت الإقفال)</label><input id="s3-fc" type="text" value="${esc((st.fixedCats||[]).join('، '))}"></div>
 <div class="field"><label for="s3-cp">تنبيه تغيّر سحب العميل لو أكتر من %</label><input id="s3-cp" type="number" value="${st.changePct}"></div><div class="field"><label for="s3-im">أقصى أيام سكون قبل تنبيه «العميل وقف»</label><input id="s3-im" type="number" value="${st.idleMax}"></div></div>
 <button class="btn" style="margin-top:12px" data-a="saveS3">حفظ</button></div>`;
 return _prefsV().replace('<div class="card" style="margin-top:16px"><h2>البراندات واللوجو</h2>',card+'<div class="card" style="margin-top:16px"><h2>البراندات واللوجو</h2>')};
const splitList=s=>s.split(/[,،\n]/).map(x=>x.trim()).filter(Boolean);
A.saveS3=async()=>{const r=Math.max(20,num('s3-r'));const geo=S.settings.geo?Object.assign({},S.settings.geo,{radius:r}):null;
 await saveSettings({radius:r,geo,graceMin:num('s3-g'),openingInv:num('s3-oi'),valMult:splitList(val('s3-vm')).map(Number).filter(x=>x>0),expCats:splitList(val('s3-ec')),fixedCats:splitList(val('s3-fc')),changePct:num('s3-cp')||20,idleMax:num('s3-im')||10});toast('اتحفظ')};
A.setGeo=()=>{if(!navigator.geolocation){toast('الجهاز ده مفيهوش تحديد موقع');return}toast('بيحدد الموقع...');navigator.geolocation.getCurrentPosition(async p=>{const r=num('s3-r')||S.settings.radius||100;
 await saveSettings({geo:{lat:+p.coords.latitude.toFixed(6),lng:+p.coords.longitude.toFixed(6),radius:r,acc:Math.round(p.coords.accuracy),at:new Date().toISOString()}});toast('اتحدد موقع المصنع (دقة '+Math.round(p.coords.accuracy)+' متر)')},e=>toast(e.code===1?'اسمح بتحديد الموقع من إعدادات المتصفح':'مش قادر يحدد الموقع، جرّب تاني'),{enableHighAccuracy:true,timeout:20000,maximumAge:0})};

// ---------- home: month profit + attention ----------
const _homeV=V.home;
V.home=()=>{if(!canSee('home')&&S.myStaff)return V.me();let html=_homeV();const extra=[];
 const pend=S.att.filter(a=>a.status==='pending').length;if(pend&&canSee('staff'))extra.push(['warn','حضور مستني اعتماد',pend+' يوم','staff','att']);
 const accr=S.accruals.filter(a=>a.amt-a.paid>0.5);if(accr.length&&canSee('expenses'))extra.push(['warn','مستحقات لسه ما اتدفعتش',accr.map(a=>a.cat).join('، '),'expenses']);
 const prev=addMonth(curMonth(),-1);if(me().owner&&!isClosed(prev)&&(S.orders.some(o=>outMonth(o)===prev)||S.expenses.some(e=>inMonth(e.d,prev))))extra.push(['bad','شهر '+mName(prev)+' لسه ما اتقفلش','اعتمد الجرد واقفل الشهر','closing']);
 const plan=S.partners.flatMap(p=>p.plan.filter(x=>!x.paid&&x.d<=daysAddISO(today(),7)).map(x=>p.name+' '+fmt(x.amt)));if(plan.length&&me().owner)extra.push(['warn','أقساط شركاء مستحقة',plan.join(' · '),'partners']);
 let box='';if(can('profit')){const m=monthPL(curMonth());box+=`<div class="grid3" style="margin-bottom:14px">${kpi('صافي ربح '+mName(curMonth())+' لحد النهارده',`<span class="${m.net>=0?'up':'down'}">${money(m.net)}</span>`,pct(m.net/(m.sales||1))+' من المبيعات · تقديري لحد الإقفال',{go:'closing'})}${kpi('المرتبات لحد النهارده',mv(m.payroll),'',{go:'staff'})}${kpi('المصروفات',mv(m.otherExp+m.dep),'شامل الإهلاك '+fmt(m.dep),{go:'expenses'})}</div>`}
 if(extra.length)box+=`<div class="card" style="margin-bottom:14px"><h2>محتاج انتباهك</h2>${extra.map(a=>`<div class="alert ${a[0]}" data-a="go" data-v="${a[3]}"${a[4]?` data-tab="${a[4]}"`:''} style="cursor:pointer;margin-top:8px"><span class="dot"></span><div><b>${esc(a[1])}</b><div class="small muted">${esc(a[2])}</div></div></div>`).join('')}</div>`;
 return box?html.replace('<div class="grid4"',box+'<div class="grid4"'):html};
const _loadAll3=loadAll;loadAll=async function(){await _loadAll3();S.closeLog=me()&&me().owner?await q('closing_log','*',{order:'at',asc:false,limit:100}):[]};
// ================= PACKAGES, BACKDATING, OLD INVOICES, OPENING BALANCE =================
// ---- backdate helpers ----
function canBD(){const u=me();return !!(u&&(u.owner||(u.perms||{}).backdate))}
function bdField(id,label){if(!canBD())return '';return `<div class="field"><label for="${id}">${label||'التاريخ'} ${ti('سيبه النهارده للعمليات العادية. التاريخ القديم بيتقبل بس في شهر مش مقفول')}</label><input id="${id}" type="date" value="${today()}" max="${today()}"></div>`}
function bdVal(id){const v=val(id);return v&&v!==today()?v:''}

// ---- packages ----
function pkgs(m){if(!m)return [];return [{n:m.pu||unitLbl(m.base),s:m.size||1}].concat(m.units||[])}
function looseInfo(base){return base==='g'?{l:'كيلو',f:1000}:base==='ml'?{l:'لتر',f:1000}:{l:unitLbl(base),f:1}}
function pkgFmt(m,q){if(!m)return '';q=+q||0;const L=looseInfo(m.base);if(m.size<=1||q<=0)return fmt(q/L.f,2)+' '+L.l;const n=Math.floor(q/m.size+1e-9);const r=q-n*m.size;
 return [n?n+' '+m.pu:'',r>0.0001?fmt(r/L.f,2)+' '+L.l:''].filter(Boolean).join(' + ')||'0'}
function puF(m,u){const p=pkgs(m)[u||0];return p&&m?p.s/(m.size||1):1}
function puUnitName(m,u){const p=pkgs(m)[u||0];return p?p.n:''}
function puUnitSel(m,l,i){const ps=pkgs(m);if(ps.length<2)return '';return `<select id="pl-u-${i}" data-chg="puCheck" style="width:110px" aria-label="العبوة">${ps.map((p,j)=>`<option value="${j}" ${(l.u||0)===j?'selected':''}>${esc(p.n)}</option>`).join('')}</select>`}
function puQ(m,l){if(!m)return +l.q||0;const p=pkgs(m)[l.u||0]||{s:m.size||1};return (+l.q||0)+(+l.l||0)*looseInfo(m.base).f/p.s}
function puConv(m,l){if(!m||!puQ(m,l))return '';const L=looseInfo(m.base);const tot=puQ(m,l)*pkgs(m)[l.u||0].s;return ` = ${fmt(tot/L.f,2)} ${L.l}`}
function compShowQ(x){if(x.k==='m'&&x.u==='g'){const m=mat(x.id);if(m&&m.pw>0)return +(x.q*m.pw).toFixed(3)}return x.q}
function compUnitSel(x,prefix,i){const m=x.k==='m'?mat(x.id):null;if(!(m&&m.base==='pc'&&m.pw>0))return '';return `<select id="${prefix}-u-${i}" style="width:74px" aria-label="الوحدة"><option value="">قطعة</option><option value="g" ${x.u==='g'?'selected':''}>جرام</option></select>`}
A.emBase=()=>{EM.base=val('em-b');matRead();matSheet()};
function unitsEditor(m){const L=looseInfo(m.base);return `<h3 style="margin-top:12px">عبوات تانية للخامة دي ${ti('لو الخامة بتيجي بأكتر من عبوة: جالون وكرتونة، أو شوال 25 وشوال 50. كل عبوة بكميتها بوحدة الوصفة. وقت الشرا والجرد هتختار العبوة، والسيستم يحوّل لوحده')}</h3>
 <p class="small muted">العبوة الأساسية: <b>${esc(m.pu||'')}</b> = ${fmt((m.size||0)/L.f,3)} ${L.l} (أسعار الموردين محسوبة عليها)</p>
 ${(m.units||[]).map((u,i)=>`<div class="row" style="flex-wrap:nowrap;margin-bottom:6px"><input type="text" id="eu-n-${i}" value="${esc(u.n)}" placeholder="اسم العبوة (كرتونة، شوال 50...)" style="flex:1"><input type="number" step="any" id="eu-s-${i}" value="${u.s?+(u.s/L.f).toFixed(4):''}" placeholder="فيها كام ${L.l}" style="width:120px"><button class="icon-btn" data-a="euDel" data-i="${i}" aria-label="حذف">×</button></div>`).join('')}
 <button class="btn sec sm" data-a="euAdd">+ عبوة</button><p class="small muted" style="margin-top:4px">مثال: ${m.base==='ml'?'كرتونة فيها 4 جوالين 4 لتر = 16':m.base==='g'?'شوال 50 = 50':m.base==='pc'?'كرتونة فيها 12 طبق بيض = 360':'لفة = 100'} ${L.l}</p>`}
A.euAdd=()=>{matRead();EM.units=(EM.units||[]).concat([{n:'',s:0}]);matSheet()};
A.euDel=el=>{matRead();EM.units.splice(+el.dataset.i,1);matSheet()};
// package-count inputs (count & opening). pk = {u0:n,u1:n,...,loose:x}
function pkQty(m,pk){if(!pk)return null;const L=looseInfo(m.base);let q=0,any=false;pkgs(m).forEach((p,j)=>{const v=pk['u'+j];if(v!==''&&v!=null){q+=(+v)*p.s;any=true}});if(pk.loose!==''&&pk.loose!=null){q+=(+pk.loose)*L.f;any=true}return any?q:null}
function pkgInputs(pre,m,pk,act,cur){if(!m)return '';pk=pk||{};const L=looseInfo(m.base);const q=pkQty(m,pk);
 return `<div class="row" style="flex-wrap:wrap;gap:4px;justify-content:flex-end">${pkgs(m).map((p,j)=>`<label class="small" style="display:flex;align-items:center;gap:3px"><input type="number" class="inp-sm" style="width:58px" id="${pre}-${m.id}-u${j}" value="${pk['u'+j]??''}" min="0" step="any" data-chg="${act}" data-live="${act}" data-v="${m.id}">${esc(p.n)}</label>`).join('')}
 ${pkgs(m).length===1&&m.size===L.f?'':`<label class="small" style="display:flex;align-items:center;gap:3px">+<input type="number" class="inp-sm" style="width:64px" id="${pre}-${m.id}-l" value="${pk.loose??''}" min="0" step="0.01" data-chg="${act}" data-live="${act}" data-v="${m.id}">${L.l} فكة</label>`}
 <span class="small muted" id="${pre}-${m.id}-t" style="min-width:90px">${q!=null?'= '+fmt(q/L.f,2)+' '+L.l:(cur!=null&&cur!==''?'= '+fmt(cur/L.f,2)+' '+L.l:'')}</span></div>`}
function pkRead(pre,m){const pk={};pkgs(m).forEach((p,j)=>{const v=val(pre+'-'+m.id+'-u'+j);if(v!=='')pk['u'+j]=+v});const l=val(pre+'-'+m.id+'-l');if(l!=='')pk.loose=+l;return pk}
A.cntPk=el=>{const m=mat(el.dataset.v);const k=today().slice(0,7);const c=S.counts[k]=S.counts[k]||{status:'draft',items:{}};const pk=pkRead('cp',m);const q=pkQty(m,pk);
 if(q==null){delete c.items['m:'+m.id];delete c.items['mb:'+m.id]}else{c.items['m:'+m.id]=+q.toFixed(4);c.items['mb:'+m.id]=pk}
 const L=looseInfo(m.base);const t=document.getElementById('cp-'+m.id+'-t');if(t)t.textContent=q!=null?'= '+fmt(q/L.f,2)+' '+L.l:'';cntRefreshCell('m:'+m.id);
 clearTimeout(_cntT);_cntT=setTimeout(async()=>{await dbx(sb.from('stock_counts').upsert({month:k,status:c.status==='approved'?'approved':'draft',items:c.items,updated_at:new Date().toISOString()},{onConflict:'month'}))},800)};

// ---- opening balance ----
function openingTab(){const op=S.settings.opening||{};const it=op.items||{};const sc=can('cost');const own=me().owner;const L=m=>looseInfo(m.base);
 const val0=Object.values(it).reduce((s,v)=>s+(v.qty||0)*(v.cost||0),0);
 return `<div class="card"><div class="between"><h2>رصيد أول المدة</h2>${op.at?`<span class="pill ok">متسجل · ${esc(op.by||'')} · ${dShort(op.date)}</span>`:'<span class="pill warn">لسه</span>'}</div>
 <p class="sub">اكتب الموجود يوم بداية السيستم. لو عدّلت بعد كده، الفرق بس هو اللي بيتظبط في الرصيد (المشتريات والفواتير اللي اتسجلت ما بتتأثرش). قيمته بتبقى مخزون أول المدة لأول إقفال.</p>
 ${!own?'<div class="lock">🔒 رصيد أول المدة للمالك بس</div>':`<div class="row" style="align-items:flex-end;gap:10px"><div class="field" style="max-width:200px"><label for="op-d">تاريخ رصيد أول المدة</label><input id="op-d" type="date" value="${op.date||curMonth()+'-01'}" max="${today()}"></div><div class="field" style="flex:1;min-width:180px"><label for="op-q">بحث</label><input id="op-q" type="text" data-live="opFilter" placeholder="اكتب اسم الصنف..."></div><button class="btn" data-a="opNew">+ صنف جديد</button></div>
 <h3 style="margin-top:12px">خامات وتغليف</h3><div class="tbl-wrap"><table><tr><th>الخامة</th><th class="n">الموجود (عبوات + فكة)</th>${sc?'<th class="n">تكلفة العبوة الأساسية</th>':''}</tr>
 ${S.materials.map(m=>{const x=it['m:'+m.id];return `<tr class="op-row" data-q="${esc(m.name)}"><td>${esc(m.name)}<div class="small muted">${esc(m.pu)} = ${fmt(m.size/L(m).f,2)} ${L(m).l}</div></td><td class="n">${pkgInputs('op',m,x&&x.pk,'opPk',x&&x.qty)}</td>${sc?`<td class="n"><input type="number" class="inp-sm" id="opc-m-${m.id}" value="${x&&x.cost?+(x.cost*m.size).toFixed(2):(m.avg?+(m.avg*m.size).toFixed(2):'')}" style="width:90px"></td>`:''}</tr>`}).join('')||'<tr><td colspan="3" class="empty">ضيف الخامات الأول</td></tr>'}</table></div>
 <h3 style="margin-top:12px">نص مصنع</h3><div class="tbl-wrap"><table><tr><th>المكون</th><th class="n">الموجود</th>${sc?'<th class="n">التكلفة (من الوصفة)</th>':''}</tr>
 ${S.recipes.map(r=>{const x=it['r:'+r.id];const lf=r.out==='g'?{l:'كيلو',f:1000}:{l:unitLbl(r.out),f:1};return `<tr class="op-row" data-q="${esc(r.name)}"><td>${esc(r.name)}</td><td class="n"><input type="number" class="inp-sm" id="opq-r-${r.id}" value="${x?+(x.qty/lf.f).toFixed(3):''}" step="0.01" style="width:90px"> ${lf.l}</td>${sc?`<td class="n small">${money(recInfo(r.id).unit*lf.f,2)} / ${lf.l}</td>`:''}</tr>`}).join('')||'<tr><td colspan="3" class="empty">مفيش</td></tr>'}</table></div>
 <h3 style="margin-top:12px">منتج تام</h3><div class="tbl-wrap"><table><tr><th>المنتج</th><th class="n">عدد القطع</th>${sc?'<th class="n">تكلفة القطعة</th>':''}</tr>
 ${S.products.map(p=>{const x=it['p:'+p.id];return `<tr class="op-row" data-q="${esc(p.name)}"><td>${esc(p.name)}</td><td class="n"><input type="number" class="inp-sm" id="opq-p-${p.id}" value="${x?x.qty:''}" style="width:80px"></td>${sc?`<td class="n small">${money(pcost(p).mat,2)}</td>`:''}</tr>`}).join('')||'<tr><td colspan="3" class="empty">مفيش</td></tr>'}</table></div>
 ${sc&&op.at?`<div class="kpi" style="margin-top:12px"><div class="l">قيمة رصيد أول المدة المتسجل</div><div class="v">${money(val0)}</div></div>`:''}
 <button class="btn block" style="margin-top:12px" data-a="openingSave">حفظ رصيد أول المدة</button>`}</div>`}
A.opPk=el=>{const m=mat(el.dataset.v);const q=pkQty(m,pkRead('op',m));const L=looseInfo(m.base);const t=document.getElementById('op-'+m.id+'-t');if(t)t.textContent=q!=null?'= '+fmt(q/L.f,2)+' '+L.l:''};
A.openingSave=async()=>{if(_busy)return;const old=(S.settings.opening||{}).items||{};const items=[];
 S.materials.forEach(m=>{const pk=pkRead('op',m);const q=pkQty(m,pk);const k='m:'+m.id;if(q==null&&!old[k])return;const cp=num('opc-m-'+m.id);items.push({kind:'m',id:m.id,qty:+(q||0).toFixed(4),unit_cost:cp?+(cp/m.size).toFixed(6):(old[k]?old[k].cost:m.avg||0),pk})});
 S.recipes.forEach(r=>{const v=val('opq-r-'+r.id);const k='r:'+r.id;if(v===''&&!old[k])return;const f=r.out==='g'?1000:1;items.push({kind:'r',id:r.id,qty:+((+v||0)*f).toFixed(4),unit_cost:+recInfo(r.id).unit.toFixed(6)})});
 S.products.forEach(p=>{const v=val('opq-p-'+p.id);const k='p:'+p.id;if(v===''&&!old[k])return;items.push({kind:'p',id:p.id,qty:+v||0,unit_cost:+pcost(p).mat.toFixed(4)})});
 if(!items.length){toast('اكتب الكميات الأول');return}if(!confirm('حفظ رصيد أول المدة وظبط الأرصدة؟'))return;
 _busy=true;try{await rpc('set_opening',{p:{date:val('op-d'),items}});await refresh();toast('اتسجل رصيد أول المدة واتظبطت الأرصدة')}finally{_busy=false}};

// ---- old invoice (one step, delivered at its date) ----
let OI=null;
A.oldInv=()=>{if(!S.customers.length){toast('ضيف عميل الأول');go('customers');return}const cu=S.customers.find(c=>c.active)||S.customers[0];const p=S.products.find(x=>x.brand===cu.brand);if(!p){toast('مفيش منتجات للبراند ده');return}
 OI={brand:cu.brand,cu:cu.id,d:daysAddISO(today(),-1),lines:[{pid:p.id,q:p.ppc>1?p.ppc:1}],courier:'',fee:0,feeOn:'us',discType:'amt',discVal:0,extras:[],paid:0,dest:'t:'+myTre(),notes:''};oiSheet()};
function oiRead(){if(!document.getElementById('oi-cu'))return;OI.cu=val('oi-cu');OI.brand=cust(OI.cu).brand;OI.d=val('oi-d');OI.lines=OI.lines.map((l,i)=>({pid:val('oil-p-'+i),q:Math.max(1,num('oil-q-'+i))}));OI.courier=val('oi-co');OI.fee=num('oi-fee');OI.discVal=num('oi-dv');OI.paid=num('oi-paid');OI.dest=val('oi-t');OI.notes=val('oi-n')}
function oiSheet(){const c=cust(OI.cu);OI.lines=OI.lines.filter(l=>prod(l.pid)&&prod(l.pid).brand===c.brand);if(!OI.lines.length){const p=S.products.find(x=>x.brand===c.brand);if(p)OI.lines=[{pid:p.id,q:1}]}const t=previewTotals(OI);const prods=S.products.filter(p=>p.brand===c.brand);
 sheet(`<h2>فاتورة قديمة</h2><p class="sub">بتتسجل «اتسلّمت» بتاريخها وبتخصم من المخزن. الرقم بيكمل الترقيم العادي.</p>
 <div class="fgrid"><div class="field"><label for="oi-d">تاريخ الفاتورة</label><input id="oi-d" type="date" value="${OI.d}" max="${today()}" data-chg="oiRe"></div><div class="field"><label for="oi-cu">العميل</label><select id="oi-cu" data-chg="oiRe">${S.customers.filter(x=>x.active).map(x=>`<option value="${x.id}" ${x.id===OI.cu?'selected':''}>${esc(x.name)} · ${esc(brand(x.brand).name)}</option>`).join('')}</select></div></div>
 ${isClosed((OI.d||'').slice(0,7))?'<div class="alert bad" style="margin-top:8px"><span class="dot"></span><div>الشهر ده مقفول. افتحه الأول من الإقفال.</div></div>':''}
 <h3 style="margin-top:12px">الأصناف</h3>${OI.lines.map((l,ix)=>`<div class="row" style="margin-bottom:8px;flex-wrap:nowrap"><select id="oil-p-${ix}" data-chg="oiRe" style="flex:1">${prods.map(x=>`<option value="${x.id}" ${x.id===l.pid?'selected':''}>${esc(x.name)}</option>`).join('')}</select><input id="oil-q-${ix}" type="number" min="1" value="${l.q}" data-chg="oiRe" style="width:76px" aria-label="الكمية"><button class="icon-btn" data-a="oiDel" data-i="${ix}" aria-label="حذف">×</button></div>`).join('')}<button class="btn sec sm" data-a="oiAdd">+ صنف</button>
 <div class="fgrid" style="margin-top:12px"><div class="field"><label for="oi-co">المندوب</label><select id="oi-co"><option value="">— استلام من المصنع —</option>${S.couriers.map(d=>`<option value="${d.id}" ${OI.courier===d.id?'selected':''}>${esc(d.name)} (${d.kind==='main'?'أساسي':'خارجي'})</option>`).join('')}</select></div>
 <div class="field"><label for="oi-fee">توصيل على العميل</label><input id="oi-fee" type="number" value="${OI.feeOn==='cust'?OI.fee:0}" data-chg="oiFee"></div>
 <div class="field"><label for="oi-dv">خصم على الفاتورة (مبلغ)</label><input id="oi-dv" type="number" value="${OI.discVal||0}" data-chg="oiRe"></div><div class="field"><label for="oi-n">ملاحظات</label><input id="oi-n" type="text" value="${esc(OI.notes)}"></div></div>
 <div class="card flat" style="margin-top:12px"><div class="between"><span>الإجمالي</span><b class="num">${money(t.total)}</b></div></div>
 <div class="fgrid" style="margin-top:10px"><div class="field"><label for="oi-paid">اتدفع منها</label><input id="oi-paid" type="number" value="${OI.paid}"></div><div class="field"><label for="oi-t">الفلوس راحت فين</label><select id="oi-t">${S.treasuries.map(x=>`<option value="t:${x.id}" ${OI.dest==='t:'+x.id?'selected':''}>${x.holder} — ${x.method}</option>`).join('')}${S.couriers.map(x=>`<option value="co:${x.id}" ${OI.dest==='co:'+x.id?'selected':''}>مع المندوب ${esc(x.name)} (عهدة)</option>`).join('')}</select></div></div>
 <p class="small muted">سيب المدفوع 0 لو الفاتورة آجل.</p><button class="btn block" style="margin-top:12px" data-a="oiSave">تسجيل الفاتورة</button>`)}
A.oiRe=()=>{oiRead();oiSheet()};A.oiFee=()=>{oiRead();OI.feeOn=OI.fee>0?'cust':'us';oiSheet()};
A.oiAdd=()=>{oiRead();const p=S.products.find(x=>x.brand===OI.brand&&!OI.lines.some(l=>l.pid===x.id))||S.products.find(x=>x.brand===OI.brand);OI.lines.push({pid:p.id,q:1});oiSheet()};
A.oiDel=el=>{oiRead();OI.lines.splice(+el.dataset.i,1);if(!OI.lines.length)A.oiAdd();else oiSheet()};
A.oiSave=async()=>{if(_busy)return;oiRead();if(!OI.d||OI.d>today()){toast('اختار تاريخ صح');return}if(isClosed(OI.d.slice(0,7))){toast('الشهر ده مقفول');return}const t=previewTotals(OI);if(OI.paid>t.total+0.01){toast('المدفوع أكبر من الإجمالي');return}
 const [k,id]=OI.dest.split(':');_busy=true;
 try{const oid=await rpc('create_old_invoice',{p:{cu:OI.cu,d:OI.d===today()?'':OI.d,fee:OI.feeOn==='cust'?OI.fee:0,fee_on:OI.feeOn,disc_type:'amt',disc_val:OI.discVal,extras:[],notes:OI.notes,courier_id:OI.courier,paid:OI.paid,treasury_id:k==='t'?id:'',pay_courier_id:k==='co'?id:'',
  lines:OI.lines.map(l=>({product_id:l.pid,qty:l.q,cost:+pcost(prod(l.pid)).mat.toFixed(4)}))}});closeSheet();await refresh();const o=ordr(oid);toast('اتسجلت '+(o?o.inv:'الفاتورة')+' بتاريخ '+dShort(OI.d));
  if(confirm('تسجل فاتورة قديمة تانية؟')){const keep={d:OI.d,dest:OI.dest};A.oldInv();Object.assign(OI,keep);oiSheet()}}finally{_busy=false}};

// ---- staff: create attendance login in one step ----
function translit(s){const M={'ا':'a','أ':'a','إ':'e','آ':'a','ب':'b','ت':'t','ث':'th','ج':'g','ح':'h','خ':'kh','د':'d','ذ':'z','ر':'r','ز':'z','س':'s','ش':'sh','ص':'s','ض':'d','ط':'t','ظ':'z','ع':'a','غ':'gh','ف':'f','ق':'k','ك':'k','ل':'l','م':'m','ن':'n','ه':'h','ة':'a','و':'o','ي':'y','ى':'a','ئ':'e','ؤ':'o','ء':''};
 return String(s||'').trim().split(/\s+/).slice(0,2).map(w=>[...w].map(ch=>M[ch]!=null?M[ch]:/[a-z0-9]/i.test(ch)?ch.toLowerCase():'').join('')).filter(Boolean).join('.')||'emp'}
function suggestEmail(name){const base=translit(name);const used=new Set(S.users.map(u=>(u.email||'').toLowerCase()));let e=base+'@melt.app',i=2;while(used.has(e)){e=base+i+'@melt.app';i++}return e}
function genPass(){const c='abcdefghjkmnpqrstuvwxyz23456789';let p='';for(let i=0;i<8;i++)p+=c[Math.floor(Math.random()*c.length)];return p}
A.staffLogin=el=>{const w=staffOf(el.dataset.v);sheet(`<h2>حساب بصمة لـ ${esc(w.name)}</h2><p class="sub">هيدخل بيه من موبايله ويشوف «حضوري ومرتبي» بس.</p><div class="fgrid">
 <div class="field full"><label for="sl-e">الإيميل ${ti('مش لازم يكون إيميل حقيقي. ده اسم الدخول بتاعه')}</label><input id="sl-e" type="text" style="direction:ltr" value="${esc(suggestEmail(w.name))}"></div>
 <div class="field full"><label for="sl-p">كلمة السر (8 حروف على الأقل)</label><input id="sl-p" type="text" style="direction:ltr" value="${genPass()}"></div></div>
 <button class="btn block" style="margin-top:12px" data-a="staffLoginSave" data-v="${w.id}">اعمل الحساب واربطه</button>`)};
A.staffLoginSave=async el=>{if(_busy)return;const w=staffOf(el.dataset.v);const email=val('sl-e').trim().toLowerCase(),password=val('sl-p').trim();
 if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)){toast('الإيميل مش مظبوط');return}if(password.length<8){toast('كلمة السر 8 حروف على الأقل');return}
 _busy=true;try{const {data,error}=await sb.functions.invoke('admin-users',{body:{action:'create',name:w.name,role:w.job||'موظف',email,password,perms:{screens:[]}}});
  if(error||data?.error){toast('مقدرتش أعمل الحساب: '+(data?.error||error.message));return}
  await dbx(sb.from('staff').update({user_id:data.id}).eq('id',w.id));await refresh();
  const link=location.origin+location.pathname;const msg=`السلام عليكم ${w.name}\nده حسابك لتسجيل الحضور في MELT:\nاللينك: ${link}\nالإيميل: ${email}\nكلمة السر: ${password}\nافتح اللينك من موبايلك وادخل، وبعدين اعمل رمز سري. سجّل «حضرت» و«مشيت» وإنت جوه المصنع.`;
  sheet(`<h2>اتعمل الحساب ✓</h2><p class="sub">ابعت البيانات دي لـ ${esc(w.name)}</p><div class="card flat" style="direction:rtl;white-space:pre-wrap;font-size:14px;line-height:1.9" id="sl-msg">${esc(msg)}</div>
  <div class="row" style="margin-top:12px"><button class="btn" data-a="copy" data-t="${esc(msg)}">نسخ الرسالة</button>${w.phone?`<a class="btn sec" href="https://wa.me/${esc(String(w.phone).replace(/\D/g,'').replace(/^0/,'20'))}?text=${encodeURIComponent(msg)}" target="_blank" rel="noopener">إرسال واتساب</a>`:''}<button class="btn ghost" data-a="close">تم</button></div>`)}finally{_busy=false}};
const _staffDetailBase=A.staffDetail;
A.staffDetail=el=>{_staffDetailBase(el);const w=staffOf(el.dataset.v);if(!me().owner)return;const box=document.querySelector('.sheet .between');if(!box)return;
 const u=w.userId?S.users.find(x=>x.id===w.userId):null;
 box.insertAdjacentHTML('afterend',w.userId?`<p class="small" style="margin:4px 0 0">📱 بيسجل من موبايله: <span style="direction:ltr;unicode-bidi:embed">${esc(u?.email||'')}</span> <button class="btn ghost sm" data-a="userPwd" data-v="${w.userId}">كلمة سر جديدة</button></p>`:`<div style="margin-top:6px"><button class="btn sm" data-a="staffLogin" data-v="${w.id}">📱 اعمل له حساب بصمة</button></div>`)};

// ---- offline: read-only from last loaded data ----
const IDB={db:null,open(){return new Promise((res,rej)=>{if(this.db)return res(this.db);const r=indexedDB.open('melt-cache',1);r.onupgradeneeded=()=>r.result.createObjectStore('kv');r.onsuccess=()=>{this.db=r.result;res(this.db)};r.onerror=()=>rej(r.error)})},
 async get(k){try{const db=await this.open();return await new Promise(res=>{const t=db.transaction('kv').objectStore('kv').get(k);t.onsuccess=()=>res(t.result||null);t.onerror=()=>res(null)})}catch(e){return null}},
 async set(k,v){try{const db=await this.open();db.transaction('kv','readwrite').objectStore('kv').put(v,k)}catch(e){}},
 async del(k){try{const db=await this.open();db.transaction('kv','readwrite').objectStore('kv').delete(k)}catch(e){}}};
const cacheKey=()=>'S:'+(SESSION&&SESSION.user&&SESSION.user.id||'');
function setOffline(on,at){S.offline=!!on;let b=document.getElementById('offline-bar');if(!on){if(b)b.remove();document.body.style.paddingTop='';return}
 if(!b){b=document.createElement('div');b.id='offline-bar';b.setAttribute('role','status');b.style.cssText='position:fixed;top:0;inset-inline:0;z-index:9999;background:#8a3b12;color:#fff;font-size:13px;text-align:center;padding:6px 12px;line-height:1.5';document.body.appendChild(b)}
 b.textContent='⚠️ مفيش نت. دي آخر بيانات اتحملت'+(at?' ('+new Date(at).toLocaleString('ar-EG',{weekday:'short',hour:'2-digit',minute:'2-digit'})+')':'')+'. التسجيل متوقف لحد ما النت يرجع.';document.body.style.paddingTop=b.offsetHeight+'px'}
async function netOk(){if(!navigator.onLine)return false;try{const {error}=await sb.from('settings').select('id').limit(1);return !(error&&/fetch|network|timeout|load failed/i.test(error.message))}catch(e){return false}}
async function useCache(){const c=await IDB.get(cacheKey());if(!c){if(!S.ready){document.getElementById('app').innerHTML=`<div class="auth"><div class="card" style="max-width:420px;margin:60px auto;text-align:center"><h2>مفيش نت</h2><p class="muted">ومفيش بيانات محفوظة على الجهاز ده لسه. أول ما النت يرجع افتح السيستم مرة، وبعد كده هيعرض آخر بيانات لو النت فصل.</p><button class="btn" onclick="location.reload()">جرّب تاني</button></div></div>`;throw new Error('offline-nocache')}setOffline(true,S.offlineAt);return}
 S=c.S;S.ready=true;S.offlineAt=c.at;recalc();setOffline(true,c.at)}
const _loadAllNet=loadAll;
loadAll=async function(){if(!(await netOk())){if(S.ready){setOffline(true,S.offlineAt||S.loadedAt);return}return useCache()}
 _netErr=false;await _loadAllNet();if(_netErr){return useCache()}
 S.loadedAt=new Date().toISOString();S.offlineAt=null;setOffline(false);try{localStorage.setItem('melt-last-uid',SESSION.user.id)}catch(e){}
 try{IDB.set(cacheKey(),{at:S.loadedAt,S:JSON.parse(JSON.stringify(S))})}catch(e){}};
async function offlineSession(){if(navigator.onLine)return null;let uid=null;try{uid=localStorage.getItem('melt-last-uid')}catch(e){}if(!uid)return null;const c=await IDB.get('S:'+uid);return c?{user:{id:uid},offline:true}:null}
window.addEventListener('offline',()=>{if(S.ready)setOffline(true,S.loadedAt)});
window.addEventListener('online',()=>{setTimeout(async()=>{try{const {data}=await sb.auth.getSession();if(data.session)SESSION=data.session;if(S.ready&&!LOCKED){await refresh();if(!S.offline)toast('النت رجع واتحدّثت البيانات')}}catch(e){}},1500)});
const _logoutBase=A_AUTH.logout;A_AUTH.logout=A.logout=async()=>{try{await IDB.del(cacheKey());localStorage.removeItem('melt-last-uid')}catch(e){}await _logoutBase()};

// ---- backup status (owner) ----
const _loadAllBk=loadAll;loadAll=async function(){await _loadAllBk();if(S.offline)return;if(me()&&me().owner){const r=await q('backup_log','*',{order:'at',asc:false,limit:1});S.lastBackup=r[0]||null}};
const _homeBk=V.home;V.home=()=>{let html=_homeBk();if(!me().owner||!S.ready)return html;const lb=S.lastBackup;const hrs=lb?(Date.now()-new Date(lb.at))/36e5:null;
 if(hrs!=null&&hrs<36)return html;const msg=lb?'آخر نسخة احتياطية من '+Math.floor(hrs/24)+' يوم':'لسه مفيش نسخة احتياطية اتعملت على Google Drive';
 return `<div class="alert ${lb?'bad':'warn'}" style="margin-bottom:12px"><span class="dot"></span><div><b>النسخة الاحتياطية</b><div class="small">${msg}. اتأكد إن سكريبت جوجل شغال.</div></div></div>`+html};
const _prefsBk=V.prefs;V.prefs=()=>{const h=_prefsBk();if(!me().owner)return h;const lb=S.lastBackup;
 return h+`<div class="card" style="margin-top:12px"><h2>النسخة الاحتياطية</h2><p class="sub">${lb?'آخر نسخة: '+new Date(lb.at).toLocaleString('ar-EG')+' · '+fmt(lb.bytes/1024,0)+' KB':'لسه مفيش نسخة اتعملت'}</p><p class="small muted">بتتعمل كل يوم الساعة 6 الصبح على Google Drive وبتوصلك على Gmail.</p></div>`};

// ---- count: live difference ----
function cntRow(kind,id){if(kind==='m'){const m=mat(id);if(!m)return null;const L=looseInfo(m.base);return {q:m.stock,uc:m.avg||0,f:q=>fmt(q/L.f,2)+' '+L.l}}
 if(kind==='r'){const r=rec(id);if(!r)return null;const lf=r.out==='g'?{l:'كيلو',f:1000}:{l:unitLbl(r.out),f:1};return {q:r.stock,uc:recInfo(id).unit,f:q=>fmt(q/lf.f,2)+' '+lf.l}}
 const p=prod(id);if(!p)return null;return {q:p.stock,uc:pcost(p).mat,f:q=>fmt(q)+' قطعة'}}
function cntDiffHTML(kind,id,a){if(a==null||a==='')return '<span class="muted">—</span>';const r=cntRow(kind,id);if(!r)return '';const d=a-r.q;
 if(Math.abs(d)<1e-6)return '<span class="up">✓ مطابق</span>';const cls=d<0?'down':'up';
 return `<span class="${cls} b">${d<0?'عجز ':'زيادة '}${r.f(Math.abs(d))}</span>${can('cost')?`<div class="small ${cls}">${d<0?'−':'+'}${fmt(Math.abs(d*r.uc))} ج</div>`:''}`}
function cntTotalsHTML(){const k=today().slice(0,7);const c=S.counts[k]||{items:{}};let loss=0,gain=0,n=0,dif=0;
 Object.entries(c.items||{}).forEach(([key,v])=>{if(!/^[mrp]:/.test(key)||v===''||v==null)return;const [kind,id]=key.split(':');const r=cntRow(kind,id);if(!r)return;n++;const dq=v-r.q;if(Math.abs(dq)>1e-6)dif++;const dv=dq*r.uc;if(dv<0)loss-=dv;else gain+=dv});
 const total=S.materials.length+S.recipes.length+S.products.length;
 return `<div class="grid4">${kpi('اتجرد',n+' من '+total)}${kpi('فيهم فرق',`${dif}`,'',{cls:dif?'down':'up'})}${can('cost')?kpi('إجمالي العجز',`<span class="down">${money(loss)}</span>`)+kpi('إجمالي الزيادة',`<span class="up">${money(gain)}</span>`):''}</div>`}
function cntRefreshCell(key){const [kind,id]=key.split(':');const c=S.counts[today().slice(0,7)]||{items:{}};const td=document.getElementById('cd-'+kind+'-'+id);if(td)td.innerHTML=cntDiffHTML(kind,id,c.items[key]);const t=document.getElementById('cnt-tot');if(t)t.innerHTML=cntTotalsHTML()}

// ---- opening: search + new item ----
A.opFilter=el=>{const q=el.value.trim().toLowerCase();document.querySelectorAll('.op-row').forEach(tr=>tr.hidden=!!q&&!tr.dataset.q.toLowerCase().includes(q))};
A.opNew=()=>sheet(`<h2>صنف جديد برصيد أول المدة</h2><p class="sub">بيتضاف للخامات ورصيده بيتسجل في نفس اللحظة. المنتجات والنص مصنع بتتضاف من شاشاتها علشان محتاجة وصفة.</p>
 <div class="fgrid"><div class="field full"><label for="on-n">الاسم</label><input id="on-n" type="text"></div>
 <div class="field"><label for="on-c">النوع</label><select id="on-c"><option value="raw">خامة</option><option value="pack">تغليف</option></select></div>
 <div class="field"><label for="on-b">وحدة الوصفة</label><select id="on-b" data-chg="onBase">${['g','ml','pc','m'].map(u=>`<option value="${u}">${unitLbl(u)}</option>`).join('')}</select></div>
 <div class="field"><label for="on-pu">العبوة</label><input id="on-pu" type="text" placeholder="شوال 25ك، جالون، كرتونة 100..."></div>
 <div class="field"><label for="on-s"><span id="on-s-l">العبوة فيها كام كيلو</span></label><input id="on-s" type="number" step="any"></div>
 <div class="field"><label for="on-q">الموجود (عدد العبوات)</label><input id="on-q" type="number" step="any"></div>
 <div class="field"><label for="on-l"><span id="on-l-l">+ فكة (كيلو)</span></label><input id="on-l" type="number" step="any"></div>
 ${can('cost')?`<div class="field full"><label for="on-cost">تكلفة العبوة</label><input id="on-cost" type="number" step="any"></div>`:''}</div>
 <button class="btn block" style="margin-top:12px" data-a="opNewSave">إضافة وتسجيل الرصيد</button>`);
A.onBase=el=>{const L=looseInfo(el.value);document.getElementById('on-s-l').textContent='العبوة فيها كام '+L.l;document.getElementById('on-l-l').textContent='+ فكة ('+L.l+')'};
A.opNewSave=async()=>{if(_busy)return;const n=val('on-n').trim(),base=val('on-b'),L=looseInfo(base),pu=val('on-pu').trim()||L.l,sz=num('on-s');
 if(!n){toast('اكتب الاسم');return}if(sz<=0){toast('اكتب العبوة فيها كام '+L.l);return}if(S.materials.some(m=>m.name.trim()===n)){toast('فيه صنف بنفس الاسم، دوّر عليه في القايمة');return}
 const size=sz*L.f,q=num('on-q')*size+num('on-l')*L.f,cost=num('on-cost');const id=uuid();
 _busy=true;try{await dbx(sb.from('materials').insert({id,name:n,cat:val('on-c'),base,pu,size,units:[],stock:0,min_stock:0}));
  if(q>0||cost>0)await rpc('set_opening',{p:{date:(S.settings.opening||{}).date||val('op-d')||today(),items:[{kind:'m',id,qty:+q.toFixed(4),unit_cost:cost?+(cost/size).toFixed(6):0,pk:{u0:num('on-q')||'',loose:num('on-l')||''}}]}});
  closeSheet();await refresh();toast('اتضاف '+n+(q>0?' برصيد '+fmt(q/L.f,2)+' '+L.l:''))}finally{_busy=false}};
